//! Safe boundary primitives for the native Apple implementation.
//!
//! This crate deliberately exposes no Objective-C pointer or fabricated
//! thread marker. Native calls and inbound callbacks should enter through
//! [`guard_native_call`], with callback adapters returning their ABI-valid
//! fallback after observing an error.

mod main_thread;
mod native_boundary;

pub use main_thread::{MainThread, MainThreadError};
pub use native_boundary::{NativeFault, NativeFaultKind, guard_native_call};
use objc2::MainThreadMarker;

/// Opaque proof that this value was acquired on Apple's process main thread.
///
/// `MainThread` is neither `Send` nor `Sync`, inherited from objc2's marker.
/// It carries no native pointer and remains valid for the lifetime of the
/// process main thread.
///
/// ```compile_fail
/// use vexel_platform_apple::MainThread;
/// fn require_send<T: Send>() {}
/// require_send::<MainThread>();
/// ```
/// ```compile_fail
/// use vexel_platform_apple::MainThread;
/// fn require_sync<T: Sync>() {}
/// require_sync::<MainThread>();
/// ```
#[derive(Clone, Copy, Debug)]
pub struct MainThread(MainThreadMarker);

/// Failure to acquire the main-thread capability from the calling thread.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct MainThreadError {
    _private: (),
}

impl MainThread {
    /// Acquires the capability only when objc2 confirms this is the main
    /// thread through its `MainThreadMarker::new` check (`pthread_main_np`).
    pub fn acquire() -> Result<Self, MainThreadError> {
        MainThreadMarker::new()
            .map(Self)
            .ok_or(MainThreadError { _private: () })
    }

    /// Gives sibling native implementation modules the binding marker while
    /// keeping it out of the crate's public API.
    #[allow(dead_code)] // Used by the native modules introduced in follow-on work orders.
    pub(crate) fn marker(&self) -> MainThreadMarker {
        self.0
    }
}
use std::panic::{AssertUnwindSafe, catch_unwind};

/// Stable categories returned by a guarded native boundary.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[non_exhaustive]
pub enum NativeFaultKind {
    /// A Rust panic or an Objective-C message exception translated to a Rust
    /// unwind by objc2's audited `catch-all` feature.
    Unwind,
}

/// Small owned error that does not retain arbitrary panic or native payloads.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct NativeFault {
    kind: NativeFaultKind,
}

impl NativeFault {
    /// Returns the bounded category for this failure.
    pub const fn kind(self) -> NativeFaultKind {
        self.kind
    }
}

/// Runs a Rust/native operation inside the reusable platform unwind guard.
///
/// Success returns the original value unchanged. Rust panics are caught by
/// `catch_unwind`; Objective-C exceptions from objc2 message sends are first
/// caught by objc2's pinned `catch-all` trampoline and converted to a Rust
/// panic, which this helper catches. The panic payload is discarded before
/// returning the fixed-size fault.
///
/// This is not a fence for raw C/CF calls, retain/release or `Drop` cleanup,
/// foreign cleanup exceptions, or operations built with `panic=abort`.
/// Those cases can terminate or escape independently. Callers must not hold
/// application-model borrows across reentrant native calls. An inbound ABI
/// callback must invoke this guard before returning and choose its own
/// ABI-valid fallback on `Err`; this helper does not invent callbacks.
pub fn guard_native_call<T>(operation: impl FnOnce() -> T) -> Result<T, NativeFault> {
    match catch_unwind(AssertUnwindSafe(operation)) {
        Ok(value) => Ok(value),
        Err(payload) => {
            discard_panic_payload(payload);
            Err(NativeFault {
                kind: NativeFaultKind::Unwind,
            })
        }
    }
}

fn discard_panic_payload(payload: Box<dyn std::any::Any + Send>) {
    // A hostile panic payload may itself panic in Drop. Catch that secondary
    // unwind so it cannot cross this boundary or double-panic the process.
    // If its own destructor panics, intentionally forget only that secondary
    // payload because no safe operation can force-drop a panicking value.
    if let Err(secondary) = catch_unwind(AssertUnwindSafe(|| drop(payload))) {
        std::mem::forget(secondary);
    }
}
use std::thread;

use objc2_foundation::NSString;
use vexel_platform_apple::{MainThread, NativeFaultKind, guard_native_call};

#[test]
fn guard_preserves_success_value() {
    let value = String::from("unchanged result");
    let result = guard_native_call(|| value).expect("success should pass through");
    assert_eq!(result, "unchanged result");
}

#[test]
fn guard_catches_rust_panic_and_discards_payload() {
    let result = guard_native_call(|| panic!("private panic payload"));
    let fault = result.expect_err("panic should become a fault");
    assert_eq!(fault.kind(), NativeFaultKind::Unwind);
}

#[test]
fn main_thread_capability_is_denied_on_spawned_thread() {
    let denied = thread::spawn(|| MainThread::acquire().is_err())
        .join()
        .expect("thread should complete");
    assert!(denied, "spawned thread must not acquire the capability");
}

#[test]
fn foundation_range_exception_is_contained_by_guard() {
    let string = NSString::from_str("native-boundary");
    let result = guard_native_call(|| {
        // NSString raises a real Foundation NSRangeException for an invalid
        // UTF-16 index. objc2 catch-all converts its Objective-C exception to
        // a Rust unwind; the reusable boundary guard contains that unwind.
        let _ = string.substringFromIndex(usize::MAX);
    });
    let fault = result.expect_err("Foundation exception should become a fault");
    assert_eq!(fault.kind(), NativeFaultKind::Unwind);
}
